import{z as s,x as l,o as A,c as d,q as r,j as B,D as e,d as E,s as o,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"盈余漂移的事件化","description":"","frontmatter":{"title":"盈余漂移的事件化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ed-pead-eventization.md","filePath":"quant/ed-pead-eventization.md","lastUpdated":1791063341000}'),p={name:"quant/ed-pead-eventization.md"};function m(h,a,D,u,c,C){const t=l("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="盈余漂移的事件化" tabindex="-1">盈余漂移的事件化 <a class="header-anchor" href="#盈余漂移的事件化" aria-label="Permalink to &quot;盈余漂移的事件化&quot;">​</a></h1><div class="epigraph"><p>漂移不在日历时间里均匀发生，而是在下一次公告附近再集中一截；按月度因子持有它，等于在信息最密的地方睡大觉。</p><footer>—— 据 Bernard and Thomas, Journal of Accounting Research, 1990；Frazzini and Lamont, Journal of Financial Economics, 2007 整理</footer></div><p><a href="/quant/ed-regulatory-event">上一课</a>收掉制度事件；本课回到财报，把五元组用到最成熟的信号上：把<a href="/quant/pead-sue">盈利意外 PEAD / SUE</a> 从月频截面因子改写成以公告为条件的事件策略。因子版按月末再平衡、持仓不看日历；事件版在公告时刻刷新、按事件日历进出。本课写改写三步——信号时点、持仓窗口、增量条件——与必须分清的两笔账：漂移与公告溢价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>因子化丢掉了三样东西。第一，<strong>信号的陈旧度</strong>。月度组合里混着刚公告与公告十周的股票，而漂移最肥的段落在公告后头几天；新旧信号等权持有，等于用闲置仓位稀释事件收益。第二，<strong>公告窗风险没有定价</strong>。因子组合被动站在每次公告旁：公告跳方向未知，波动与价差先加宽再回落。事件化要显式回答：跨公告持有是收溢价还是躲跳变。第三，<strong>增量信息没有合并窗口</strong>。<a href="/quant/earnings-call-tone">电话会语气</a>的残差语气、指引修订与 SUE 在同一个事件簇里，因子框架里只是另一列特征；事件框架里有天然的合并时点——公告本身。</p><p><span class="marginnote">直觉类比：信号像面包，有新鲜度。月度因子组合把刚出炉和放了十周的面包混在一个篮子里卖；漂移最「新鲜」的段落是公告后头几天，新旧等权等于用陈面包稀释刚出炉的——篮子看起来还是面包，味道已经被平均掉。</span></p><h3 id="多季结构的约束" tabindex="-1">多季结构的约束 <a class="header-anchor" href="#多季结构的约束" aria-label="Permalink to &quot;多季结构的约束&quot;">​</a></h3><p>Bernard 与 Thomas 的发现里有因子框架装不下的细节：漂移在下一、二、三季的公告窗附近再次集中，到第四季往往反号。持仓窗口必须围绕多季结构设计，而不是用单一持有期常数把它平均掉。</p><p><span class="marginnote">Livnat 与 Mendenhall（2006）：分析师预测算的 SUE 比时间序列模型算的漂移更强，公告前后机构交易越活跃漂移越大——信号定义与事件窗定义互相咬合，不能各改各的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>信号在公告时刻刷新。</strong> 公告落地即算 SUE、更新语气残差与指引状态，事件表按 \\((T, \\mathrm{SUE}, \\ldots)\\) 入库；未刷新的旧信号不进当期组合。不这么做会错在哪：陈旧信号把「公告后第 1 天建仓」混成「第 60 天建仓」，事件的时序结构全部抹平。</p><p><strong>窗口对准漂移的时序。</strong> 持仓写成两段：公告后 \\(N\\) 日的主窗（漂移最陡），加上下一季公告窗的副窗（漂移再集中处），第四季反号前清仓或反转。同日扎堆按截面分组：单票风险二值，几十票同日公告的组合才是统计意义上的漂移。</p><p><strong>公告账单独记。</strong> 持有主窗赚漂移；跨公告持有，额外赚公告溢价（Frazzini 与 Lamont，2007：财报周的收益系统性高于非财报周）并承担跳变。策略必须显式选择——避开公告窗（主窗在公告后起算，自动避开下次公告），或保留跨季副窗（赚溢价、付跳变）；两者波动预算不同。</p><p><span class="marginnote">术语翻译：「跨公告持有是卖保险」——你像保险公司一样承保公告日的突发跳变（方向未知、价差摆动），财报周的超额收益就是收到的保费。主窗在公告后才建仓的策略则躲开承保期，只赚漂移、不收保费，也不会被跳变击中。</span></p>',14)),(A(),B(i,null,{default:e(()=>[o(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%85%AC%E5%91%8A%E6%97%B6%E6%88%B3%22%5D%20--%3E%20REF%5B%22%E5%88%B7%E6%96%B0%20SUE%20%E4%B8%8E%E8%AF%AD%E6%B0%94%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20REF%20--%3E%20GRP%5B%22SUE%20%E6%88%AA%E9%9D%A2%E5%88%86%E7%BB%84%22%5D%0A%20%20GRP%20--%3E%20MAIN%5B%22%E4%B8%BB%E7%AA%97%EF%BC%9A%E5%85%AC%E5%91%8A%E5%90%8E%20N%20%E6%97%A5%22%5D%0A%20%20MAIN%20--%3E%20SUB%5B%22%E5%89%AF%E7%AA%97%EF%BC%9A%E4%B8%8B%E5%AD%A3%E5%85%AC%E5%91%8A%E7%AA%97%22%5D%0A%20%20SUB%20--%3E%20Q4%7B%22%E4%B8%B4%E8%BF%91%E7%AC%AC%E5%9B%9B%E5%AD%A3%EF%BC%9F%22%7D%0A%20%20Q4%20--%3E%7C%22%E6%98%AF%22%7C%20EXIT%5B%22%E6%B8%85%E4%BB%93%E6%88%96%E5%8F%8D%E8%BD%AC%EF%BC%9A%E6%BC%82%E7%A7%BB%E5%8F%8D%E5%8F%B7%22%5D%0A%20%20Q4%20--%3E%7C%22%E5%90%A6%22%7C%20HOLD%5B%22%E7%BB%A7%E7%BB%AD%E6%8C%81%E6%9C%89%E5%89%AF%E7%AA%97%22%5D%0A%20%20MAIN%20--%3E%20PREM%5B%22%E5%85%AC%E5%91%8A%E8%B4%A6%EF%BC%9A%E6%BA%A2%E4%BB%B7%E4%B8%8E%E8%B7%B3%E5%8F%98%E5%88%86%E8%AE%B0%22%5D%0A%20%20SUB%20--%3E%20PREM%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,[E("事件化能提高可实现收益，机制在于"),n("strong",null,"持有期对准了信息处理期"),E("。漂移由系统性反应不足驱动，反应不足在公告时产生：预期形成、意外落地、注意力集中都在公告窗。因子版把资金摊在两个公告之间的日历时间，事件版集中到信息处理的时段，闲置的中间段让出来。多季再集中是同一反应不足的重复：投资者修正了这一季的意外，仍按旧模型外推下一季（Bernard 与 Thomas 押在盈余自相关的错误先验上），新公告每次都再触发一段修正。第四季反号则是修正过度：市场最终学会外推，把前几季的欠账补过头。")],-1)),(A(),B(i,null,{default:e(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAME%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E8%B5%84%E9%87%91%22%5D%20--%3E%20FAC%5B%22%E5%9B%A0%E5%AD%90%E7%89%88%3A%20%E6%9C%88%E6%9C%AB%E5%86%8D%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20FAC%20--%3E%20F1%5B%22%E8%B5%84%E9%87%91%E6%91%8A%E5%9C%A8%E4%B8%A4%E4%B8%AA%E5%85%AC%E5%91%8A%E4%B9%8B%E9%97%B4%E7%9A%84%E6%97%A5%E5%8E%86%E6%97%B6%E9%97%B4%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E5%88%9A%E5%85%AC%E5%91%8A%E4%B8%8E%E5%85%AC%E5%91%8A%E5%8D%81%E5%91%A8%E7%9A%84%E5%90%8D%E5%AD%97%E7%AD%89%E6%9D%83%3A%20%E9%99%88%E6%97%A7%E7%A8%80%E9%87%8A%22%5D%0A%20%20SAME%20--%3E%20EVT%5B%22%E4%BA%8B%E4%BB%B6%E7%89%88%3A%20%E5%85%AC%E5%91%8A%E6%97%B6%E5%88%BB%E5%88%B7%E6%96%B0%22%5D%0A%20%20EVT%20--%3E%20E1%5B%22%E8%B5%84%E9%87%91%E9%9B%86%E4%B8%AD%E5%88%B0%E5%85%AC%E5%91%8A%E5%90%8E%E4%B8%BB%E7%AA%97%22%5D%0A%20%20E1%20--%3E%20E2%5B%22%E9%97%B2%E7%BD%AE%E7%9A%84%E4%B8%AD%E9%97%B4%E6%AE%B5%E8%AE%A9%E5%87%BA%E6%9D%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>公告溢价的机制反着写：跨公告持有是卖保险——公告日的双跳风险（方向未知、流动性摆动）由持有者承担，补偿是财报周的超额收益。事件化把这笔保险从被动承担变成显式选择。</p><p><span class="marginnote">常见误区：以为漂移会线性延续，把副窗一直拿到第 N 季。证据是第四季常反号——市场最终学会外推，把前几季欠账补过头；不设反号检查点，前几季赚的漂移可能在第四季整段还回去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>成本与小盘偏倚沿用<a href="/quant/pead-sue">盈利意外 PEAD / SUE</a> 的口径：等权小盘样本会高估可实现收益，主窗换手按事件频率而非月频计费。预告与快报不与正式公告混表（第 1 课边界继续有效）。漂移强度随资本进入衰减，多季结构在公开化高的市场变浅——历史窗口参数不能直接外推。事件化不是免费午餐：月频分散组合换成事件日的集中建仓，扎堆与容量约束在事件框架里更紧，不是更松。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三步：信号在公告时刻刷新、窗口对准漂移时序、增量信息在事件簇内合并。</li><li>持仓分主窗副窗：公告后 N 日是漂移主段，下一季公告窗是再集中处，第四季反号前离场。</li><li>两笔账分记：主窗赚漂移，跨公告赚溢价并承担跳变；选择要显式。</li><li>陈旧信号与月度再平衡抹平事件时序；事件表按公告时戳入库。</li><li>出处：Bernard and Thomas, <em>Journal of Accounting Research</em>, 1989/1990；Livnat and Mendenhall, <em>JAR</em>, 2006；Frazzini and Lamont, <em>Journal of Financial Economics</em>, 2007；Ball and Brown, <em>JAR</em>, 1968。</li></ul>',6))])}const F=s(p,[["render",m]]);export{g as __pageData,F as default};
